import { useState, useEffect } from 'react';
import Header from './components/Header';
import ControlPanel from './components/ControlPanel';
import ChartPanel from './components/ChartPanel';
import InsightsPanel from './components/InsightsPanel';
import SentimentPanel from './components/SentimentPanel';
import ApiModal from './components/ApiModal';
import Toast from './components/Toast';
import { fetchHistorical } from './hooks/useMarketStack';

function App() {
  const [symbols, setSymbols] = useState(['AAPL']);
  const [range, setRange] = useState('YTD');
  const [series, setSeries] = useState({});
  const [loading, setLoading] = useState(false);
  const [openaiKey, setOpenaiKey] = useState(null);
  const [showApiModal, setShowApiModal] = useState(false);
  const [toastMsg, setToastMsg] = useState('');
  const [showToast, setShowToast] = useState(false);

  useEffect(() => {
    loadKeys();
  }, []);

  useEffect(() => {
    if (symbols.length > 0) {
      updateAll(false);
    }
  }, [symbols, range]);

  function loadKeys() {
    setOpenaiKey(localStorage.getItem('OPENAI_KEY') || null);
  }

  function displayToast(msg) {
    setToastMsg(msg);
    setShowToast(true);
    setTimeout(() => setShowToast(false), 1800);
  }

  async function updateAll(force = false) {
    if (loading) return;
    setLoading(true);

    try {
      const grouped = await fetchHistorical(symbols, range);
      const newSeries = {};
      symbols.forEach(sym => {
        newSeries[sym] = grouped[sym] || [];
      });
      setSeries(newSeries);
    } catch (e) {
      console.error(e);
      displayToast(e.message || 'Update failed');
    } finally {
      setLoading(false);
    }
  }

  function addSymbol(symbol) {
    const sym = symbol.trim().toUpperCase();
    if (!sym) return;
    if (!/^[A-Z.\-]{1,10}$/.test(sym)) {
      displayToast('Invalid symbol');
      return;
    }
    if (!symbols.includes(sym)) {
      setSymbols([...symbols, sym]);
    } else {
      displayToast(`${sym} already added`);
    }
  }

  function removeSymbol(symbol) {
    setSymbols(symbols.filter(s => s !== symbol));
    const newSeries = { ...series };
    delete newSeries[symbol];
    setSeries(newSeries);
  }

  return (
    <div className="antialiased bg-neutral-950 text-neutral-200 font-sans selection:bg-indigo-500/30 selection:text-indigo-200">
      <div className="min-h-screen flex flex-col">
        <div className="bg-yellow-200/70 text-yellow-950 text-xs sm:text-sm text-center py-2 px-4">
          This app is built using the{' '}
          <a
            href="https://marketstack.com/"
            className="underline decoration-dotted underline-offset-2"
            target="_blank"
            rel="noreferrer"
          >
            Marketstack API
          </a>
          .
        </div>
        <Header
          onOpenApiModal={() => setShowApiModal(true)}
          onRefresh={() => updateAll(true)}
          loading={loading}
        />

        <main className="flex-1">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
            <section className="grid grid-cols-1 xl:grid-cols-12 gap-6">
              <div className="xl:col-span-9">
                <ControlPanel
                  symbols={symbols}
                  range={range}
                  onAddSymbol={addSymbol}
                  onRemoveSymbol={removeSymbol}
                  onRangeChange={setRange}
                />
                <ChartPanel series={series} symbols={symbols} range={range} />
              </div>

              <aside className="xl:col-span-3 flex flex-col gap-6">
                <InsightsPanel
                  symbols={symbols}
                  series={series}
                  range={range}
                  openaiKey={openaiKey}
                  onToast={displayToast}
                />
                <SentimentPanel symbols={symbols} series={series} range={range} />
              </aside>
            </section>

            <div className="mt-8 text-[13px] text-neutral-500 border-t border-neutral-900 pt-4 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-2">
              <div>Data via MarketStack. Charts by FusionCharts. Insights by GPT. Delayed data may apply.</div>
              <div>For demonstration only. Not investment advice.</div>
            </div>
          </div>
        </main>
      </div>

      <ApiModal
        show={showApiModal}
        onClose={() => setShowApiModal(false)}
        onSave={() => {
          loadKeys();
          updateAll(true);
          displayToast('Keys saved');
        }}
        onToast={displayToast}
      />

      <Toast show={showToast} message={toastMsg} />
    </div>
  );
}

export default App;

import { useEffect, useState } from 'react';
import { fmtPct } from '../utils/helpers';

export default function SentimentPanel({ symbols, series }) {
  const [breadth, setBreadth] = useState('—');
  const [avgReturn, setAvgReturn] = useState('—');
  const [sentiment, setSentiment] = useState({ label: 'Neutral', className: 'bg-neutral-800 text-neutral-300 ring-neutral-700' });

  useEffect(() => {
    computeSentiment();
  }, [symbols, series]);

  function computeSentiment() {
    const perfs = [];
    symbols.forEach(sym => {
      const arr = series[sym];
      if (!arr || arr.length < 2) return;
      const start = arr[0].close;
      const end = arr[arr.length - 1].close;
      const pct = (end - start) / (start || 1);
      perfs.push(pct);
    });

    if (!perfs.length) {
      setBreadth('—');
      setAvgReturn('—');
      setSentiment({ label: 'Neutral', className: 'bg-neutral-800 text-neutral-300 ring-neutral-700' });
      return;
    }

    const up = perfs.filter(p => p > 0).length;
    const breadthPct = up / perfs.length;
    const avg = perfs.reduce((a, b) => a + b, 0) / perfs.length;

    setBreadth(`${Math.round(breadthPct * 100)}%`);
    setAvgReturn(fmtPct(avg));

    let label = 'Neutral';
    let className = 'bg-neutral-800 text-neutral-300 ring-neutral-700';

    if (avg > 0.01 && breadthPct >= 0.6) {
      label = 'Bullish';
      className = 'bg-emerald-900/30 text-emerald-300 ring-emerald-700/50';
    } else if (avg < -0.01 && breadthPct <= 0.4) {
      label = 'Bearish';
      className = 'bg-rose-900/30 text-rose-300 ring-rose-700/50';
    }

    setSentiment({ label, className });
  }

  return (
    <div className="rounded-xl border border-neutral-800 bg-neutral-900/40">
      <div className="p-4 border-b border-neutral-800 flex items-center justify-between">
        <div className="text-sm font-medium tracking-tight">Market Sentiment</div>
        <div className={`inline-flex items-center gap-1.5 px-2 py-1 rounded-md text-xs ring-1 ${sentiment.className}`}>
          {sentiment.label}
        </div>
      </div>
      <div className="p-4">
        <div className="flex items-end gap-6">
          <div className="flex-1">
            <div className="text-xs text-neutral-500 mb-1">Breadth (↑ last period)</div>
            <div className="flex items-center gap-2">
              <div className="text-2xl tracking-tight font-semibold">{breadth}</div>
              <div className="text-xs text-neutral-500">of selected symbols</div>
            </div>
          </div>
          <div className="flex-1">
            <div className="text-xs text-neutral-500 mb-1">Avg. return (period)</div>
            <div className="text-2xl tracking-tight font-semibold">{avgReturn}</div>
          </div>
        </div>
        <div className="mt-4 text-xs text-neutral-500">
          Sentiment is calculated from price change over the chosen timeframe across selected symbols.
        </div>
      </div>
    </div>
  );
}

export async function generateInsights(symbols, series, range, horizon, openaiKey) {
  const all = {};
  symbols.forEach(sym => {
    const arr = series[sym] || [];
    all[sym] = arr.map(p => ({ date: p.date, close: p.close, volume: p.volume }));
  });

  if (Object.keys(all).length === 0 || Object.values(all).every(a => a.length === 0)) {
    throw new Error('No data to analyze. Add symbols and fetch data first.');
  }

  const payload = {
    horizon,
    range,
    symbols,
    series: all
  };

  if (openaiKey) {
    const sys = 'You are a market analyst. Provide concise, neutral, non-promissory insights. Avoid financial advice. Use bullet points when helpful. Keep under 150 words.';
    const user = `Analyze these symbols over ${range} with ${horizon}-term focus. Provide trend, momentum, support/resistance zones if clear, and risks. Data: ${JSON.stringify(payload)}`;

    const res = await fetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${openaiKey}`
      },
      body: JSON.stringify({
        model: 'gpt-4o-mini',
        messages: [
          { role: 'system', content: sys },
          { role: 'user', content: user }
        ],
        temperature: 0.3,
        max_tokens: 300
      })
    });

    if (!res.ok) throw new Error('GPT request failed');
    const data = await res.json();
    return data.choices?.[0]?.message?.content?.trim() || 'No insight generated.';
  } else {
    // Backend proxy example
    const res = await fetch('/api/gpt-insights', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });

    if (!res.ok) throw new Error('Backend insight request failed');
    const data = await res.json();
    return data.insights || 'No insight generated.';
  }
}

export function showToast(msg, toastElement, toastMsgElement) {
  toastMsgElement.textContent = msg;
  toastElement.classList.remove('hidden');
  setTimeout(() => toastElement.classList.add('hidden'), 1800);
}

export function fmtPct(x) {
  const sign = x > 0 ? '+' : '';
  return `${sign}${(x * 100).toFixed(2)}%`;
}

export function dateISO(d) {
  return d.toISOString().split('T')[0];
}

export function rangeToDates(range) {
  const end = new Date();
  const start = new Date();

  switch (range) {
    case '1M':
      start.setMonth(end.getMonth() - 1);
      break;
    case '3M':
      start.setMonth(end.getMonth() - 3);
      break;
    case '6M':
      start.setMonth(end.getMonth() - 6);
      break;
    case '1Y':
      start.setFullYear(end.getFullYear() - 1);
      break;
    case '5Y':
      start.setFullYear(end.getFullYear() - 5);
      break;
    case 'YTD':
    default:
      start.setMonth(0);
      start.setDate(1);
      break;
  }

  return { from: dateISO(start), to: dateISO(end) };
}

